let navNormal=normalAt(0,71),forward=new T.Vector3(0,0,-1).projectOnPlane(navNormal).normalize(),climb=null;
player.position.copy(surface(navNormal));player.visible=false;
let mode='intro',startTime=0,pitch=.12,moving=0,walk=0,facing=Math.PI;const clock=new T.Clock();const joy={x:0,y:0,id:null},keys=new Set();const viewTarget=new T.Vector3(),desired=new T.Vector3();
function activeUp(){return climb?towerUp.clone():navNormal.clone().negate();}
function turnView(angle){forward.applyAxisAngle(activeUp(),angle).normalize();}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);}addEventListener('resize',resize);if(window.visualViewport)visualViewport.addEventListener('resize',resize);
function interior(){world.visible=true;outside.visible=false;scene.background=new T.Color('#aabca0');scene.fog=new T.Fog('#b8c7a9',350,1450);}
function beginWalk(){mode='walk';interior();player.visible=true;$('hud').hidden=false;$('intro').style.display='none';updateCamera(1);setTimeout(()=>$('lookhint').style.opacity='.2',7000);}
$('enter').addEventListener('click',()=>{if(mode!=='intro')return;mode='approach';startTime=clock.elapsedTime;$('intro').style.opacity=0;$('intro').style.pointerEvents='none';});
function clearInput(){keys.clear();joy.x=joy.y=0;joy.id=null;lookId=null;$('knob').style.transform='';}let lookId=null,lastX=0,lastY=0;
const stick=$('stick');stick.addEventListener('pointerdown',e=>{if(joy.id!==null)return;e.preventDefault();joy.id=e.pointerId;stick.setPointerCapture(e.pointerId);updateJoy(e);});function updateJoy(e){const r=stick.getBoundingClientRect();let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;const d=Math.hypot(x,y),limit=37;if(d>limit){x*=limit/d;y*=limit/d;}joy.x=x/limit;joy.y=y/limit;$('knob').style.transform=`translate(${x}px,${y}px)`;}stick.addEventListener('pointermove',e=>{if(e.pointerId===joy.id)updateJoy(e);});for(const evt of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(evt,e=>{if(e.pointerId===joy.id){joy.x=joy.y=0;joy.id=null;$('knob').style.transform='';}});
renderer.domElement.addEventListener('pointerdown',e=>{if(mode!=='walk'||lookId!==null)return;lookId=e.pointerId;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerId!==lookId)return;turnView(-(e.clientX-lastX)*.005);pitch=T.MathUtils.clamp(pitch+(e.clientY-lastY)*.005,-.65,1.54);lastX=e.clientX;lastY=e.clientY;$('lookhint').style.opacity='0';});for(const evt of ['pointerup','pointercancel','lostpointercapture'])renderer.domElement.addEventListener(evt,e=>{if(lookId===e.pointerId)lookId=null;});
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{clearInput();clock.getDelta();});
$('home').addEventListener('click',()=>{clearInput();climb=null;navNormal=normalAt(28,12);forward.set(0,0,-1).projectOnPlane(navNormal).normalize();player.position.copy(surface(navNormal));pitch=.12;updateCamera(1);});$('full').addEventListener('click',async()=>{try{if(!document.fullscreenElement){await document.documentElement.requestFullscreen?.();}else await document.exitFullscreen();}catch{}});
renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('error').hidden=false;});
function towerLocal(p){return p.clone().sub(towerOrigin).applyQuaternion(towerInverse);}
function towerWorld(p){return new T.Vector3(p.x,p.y,p.z).applyQuaternion(towerQ).add(towerOrigin);}
function setClimb(p){climb=p;forward.projectOnPlane(towerUp).normalize();player.position.copy(towerWorld(p));}
function updateCamera(dt){const up=activeUp();camera.up.copy(up);const eye=player.position.clone().addScaledVector(up,2.4);const view=forward.clone().multiplyScalar(Math.cos(pitch)).addScaledVector(up,Math.sin(pitch)).normalize();const offset=Math.max(1.1,9*(1-Math.max(0,pitch)/1.65));desired.copy(eye).addScaledVector(forward,-offset).addScaledVector(up,.65);const radial=desired.clone().sub(CENTER),r=radial.length();if(r>1){const n=radial.divideScalar(r),max=RADIUS-relief(n)-.8;if(r>max)desired.copy(CENTER).addScaledVector(n,max);}camera.position.lerp(desired,1-Math.exp(-dt*12));viewTarget.copy(camera.position).addScaledVector(view,80);camera.lookAt(viewTarget);const nearSun=player.position.distanceTo(CENTER);solarMat.opacity=nearSun<32?Math.max(.05,(nearSun-15)/17*.95):.95;halo.visible=nearSun>32;}
function move(dt){let side=joy.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('q')||keys.has('a')||keys.has('arrowleft')?1:0),ahead=-joy.y+(keys.has('z')||keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0);const length=Math.hypot(side,ahead);moving=Math.min(1,length);if(length>.06){side/=Math.max(1,length);ahead/=Math.max(1,length);const up=activeUp(),right=forward.clone().cross(up).normalize(),direction=forward.clone().multiplyScalar(ahead).addScaledVector(right,side).normalize();
if(climb){const delta=direction.clone().applyQuaternion(towerInverse).multiplyScalar(dt*8*moving),x=climb.x+delta.x,z=climb.z+delta.z;let next=towerStep(x,z,climb.y);if(!next)next=towerStep(x,climb.z,climb.y);if(!next)next=towerStep(climb.x,z,climb.y);if(next){climb=next;player.position.copy(towerWorld(next));}else if(climb.y<1.4&&Math.hypot(x,z)>10.4){navNormal=towerWorld({x,y:0,z}).sub(CENTER).normalize();forward.projectOnPlane(navNormal).normalize();climb=null;player.position.copy(surface(navNormal));}}
else{const c=chart(navNormal),speed=Math.hypot(c.x,c.z)<115?12:22;let next=advanceFrame(navNormal,forward,side,ahead,dt*speed);if(surfaceBlocked(next.normal)){next=advanceFrame(navNormal,forward,side,0,dt*speed);if(surfaceBlocked(next.normal))next=advanceFrame(navNormal,forward,0,ahead,dt*speed);}if(!surfaceBlocked(next.normal)){navNormal=next.normal;forward=next.forward;player.position.copy(surface(navNormal));const local=towerLocal(player.position);if(Math.abs(local.y)<1.5){const h=stairHeight(local.x,local.z,local.y);if(h!==null)setClimb({x:local.x,z:local.z,y:h});}}}
const newUp=activeUp(),face=forward.clone().multiplyScalar(ahead).addScaledVector(forward.clone().cross(newUp).normalize(),side).normalize();const basis=new T.Matrix4().makeBasis(newUp.clone().cross(face).normalize(),newUp,face);player.quaternion.slerp(new T.Quaternion().setFromRotationMatrix(basis),Math.min(1,dt*14));walk+=dt*11*moving;
}else{const oldUp=new T.Vector3(0,1,0).applyQuaternion(player.quaternion),q=new T.Quaternion().setFromUnitVectors(oldUp,activeUp());player.quaternion.premultiply(q);}
legs.forEach((l,i)=>l.rotation.x=Math.sin(walk+i*Math.PI)*.45*moving);arms.forEach((a,i)=>a.rotation.x=-Math.sin(walk+i*Math.PI)*.4*moving);robe.position.y=.9+Math.abs(Math.sin(walk))*.035*moving;const up=activeUp();playerShadow.position.copy(player.position).addScaledVector(up,.03);playerShadow.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),up);updateCamera(dt);}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.045),t=clock.elapsedTime;
if(mode==='intro'){camera.up.set(0,1,0);camera.position.set(520+Math.sin(t*.07)*35,240,1040);camera.lookAt(0,30,0);}
else if(mode==='approach'){const u=(t-startTime)/4.5;if(u<1){const s=u*u*(3-2*u);camera.position.set(520*(1-s),240*(1-s)+15*s,1040*(1-s)+294*s);camera.lookAt(0,15,276);$('fade').style.opacity=u>.85?String((u-.85)/.15):'0';}else{mode='tunnel';startTime=t;interior();$('fade').style.opacity='0';}}
else if(mode==='tunnel'){const u=Math.min(1,(t-startTime)/6),s=u*u*(3-2*u);const tunnelQ=orientation(normalAt(0,118));camera.position.copy(new T.Vector3(0,4,35-s*73).applyQuaternion(tunnelQ).add(surfacePoint(0,118)));camera.up.copy(normalAt(0,118).negate());const target=surfacePoint(0,45,15);camera.lookAt(target);if(u>=1)beginWalk();}else move(dt);
if(world.visible){bear.scale.y=1+Math.sin(t*1.3)*.018;ripples.forEach(r=>{const s=1+((t*.35+r.userData.phase)%3);r.scale.set(s*1.5,s,1);r.material.opacity=.15*(1-(s-1)/3);});waterMat.color.setHSL(.485+Math.sin(t*.3)*.008,.39,.5);}
renderer.render(scene,camera);}
